INSERT INTO SneakerMarketDB.dbo.products (brand_id,category_id,product_name,description,status,created_at,updated_at) VALUES
                                                                                                                          (2,1,N'Air Jordan 1 Retro High OG "Banned"',N'經典芝加哥配色，皮革質感上乘，球鞋收藏家必備。',N'ON_SALE','2026-08-08 13:56:28','2026-08-08 13:56:28'),
                                                                                                                          (1,1,N'Nike Hyperdunk',N'亮眼反轉聖誕怪傑配色，搭 Zoom Turbo 緩震。',N'ON_SALE','2026-08-08 13:56:28','2026-08-08 13:56:28'),
                                                                                                                          (3,3,N'adidas Samba OG',N'復古德訓鞋型，皮革鞋面搭麂皮 T 字鞋頭，街頭百搭。',N'ON_SALE','2026-08-08 13:56:28','2026-08-08 13:56:28'),
                                                                                                                          (4,2,N'New Balance 990',N'美製 990 系列，搭載 FuelCell 中底科技，極致舒適。',N'ON_SALE','2026-08-08 13:56:28','2026-08-08 13:56:28'),
                                                                                                                          (1,2,N'Nike Free+ 3',N'經典小飛象跑鞋，React 泡棉雙重 Zoom Air 氣墊。',N'ON_SALE','2026-08-08 13:56:28','2026-08-08 13:56:28'),
                                                                                                                          (2,1,N'Air Jordan 4 Retro "Cement Grey"',N'復古網格與經典藍白配色，網球與籃球跨界經典。',N'ON_SALE','2026-08-08 13:56:28','2026-08-08 13:56:28'),
                                                                                                                          (3,3,N'adidas Stan Smith',N'70 年代室內運動鞋演變，透明膠底與麂皮鞋面。',N'ON_SALE','2026-08-08 13:56:28','2026-08-08 13:56:28'),
                                                                                                                          (4,2,N'New Balance 1225',N'千禧年 Y2K 機能風跑鞋，N-ergy 避震中底。',N'ON_SALE','2026-08-08 13:56:28','2026-08-08 13:56:28'),
                                                                                                                          (5,4,N'Vans Authentic',N'經典側邊白條紋，麂皮與帆布拼接，耐磨鬆餅大底。',N'ON_SALE','2026-08-08 13:56:28','2026-08-08 13:56:28'),
                                                                                                                          (1,1,N'Nike Air Force 1 ''07',N'Devin Booker 首雙簽名鞋，兼具場上性能與場下生活穿搭。',N'ON_SALE','2026-08-08 13:56:28','2026-08-08 13:56:28'),
                                                                                                                          (1,2,N'Nike Air Max 90',N'經典氣墊跑鞋，可視化 Air 氣墊搭配撞色拼接，休閒運動百搭款。',N'ON_SALE','2026-09-05 15:58:24','2026-09-05 15:58:24'),
                                                                                                                          (1,3,N'Nike Dunk Low',N'低筒經典鞋型，撞色拼接鞋面，街頭穿搭必備單品。',N'ON_SALE','2026-09-05 15:58:24','2026-09-05 15:58:24'),
                                                                                                                          (2,1,N'Air Jordan 13 Retro',N'致敬喬丹生涯代表作之一，豹紋鞋墊與外底設計獨具特色。',N'ON_SALE','2026-09-05 15:58:24','2026-09-05 15:58:24'),
                                                                                                                          (2,1,N'Air Jordan 17',N'可拆式鞋舌保護殼，科技感十足的籃球鞋款。',N'ON_SALE','2026-09-05 15:58:24','2026-09-05 15:58:24'),
                                                                                                                          (3,3,N'adidas Superstar',N'貝殼頭經典鞋型，三條線標誌性設計，休閒百搭首選。',N'ON_SALE','2026-09-05 15:58:24','2026-09-05 15:58:24'),
                                                                                                                          (3,2,N'adidas Ultraboost',N'Boost 中底提供極佳緩震回彈，Primeknit 鞋面包覆性佳，適合日常慢跑。',N'ON_SALE','2026-09-05 15:58:24','2026-09-05 15:58:24'),
                                                                                                                          (4,2,N'New Balance 574',N'經典跑鞋鞋型，麂皮與網布拼接，復古慢跑風格代表作。',N'ON_SALE','2026-09-05 15:58:24','2026-09-05 15:58:24'),
                                                                                                                          (4,3,N'New Balance 373',N'簡約百搭休閒鞋款，日常穿搭好選擇。',N'ON_SALE','2026-09-05 15:58:24','2026-09-05 15:58:24'),
                                                                                                                          (5,4,N'Vans Old Skool',N'經典側邊條紋設計，帆布與麂皮拼接鞋面，滑板文化代表鞋款。',N'ON_SALE','2026-09-05 15:58:24','2026-09-05 15:58:24'),
                                                                                                                          (5,4,N'Vans Sk8-Hi',N'高筒滑板鞋，加強腳踝防護與耐磨大底，街頭滑板風格必備。',N'ON_SALE','2026-09-05 15:58:24','2026-09-05 15:58:24');
